import {parseInfo,positionAt,validateAnalysisPosition} from './core.js';
export class Engine {
  constructor(onStatus=()=>{}){this.onStatus=onStatus;this.worker=null;this.ready=false;this.listeners=new Set();this.searching=false;this.initPromise=null;this.generation=0;}
  send(command){this.worker.postMessage({type:'command',command});}
  waitFor(test,timeout=20000){return new Promise((resolve,reject)=>{const cleanup=()=>{clearTimeout(timer);this.listeners.delete(listener);};const timer=setTimeout(()=>{cleanup();reject(Error('エンジンの応答がありません。再読み込みしてください。'));},timeout);const listener=msg=>{if(msg.type==='error'){cleanup();reject(Error(msg.message));}else if(test(msg)){cleanup();resolve(msg);}};this.listeners.add(listener);});}
  async init(){if(this.ready)return;if(this.initPromise)return this.initPromise;this.initPromise=this.initialize().catch(e=>{this.terminate();throw e;});return this.initPromise;}
  async initialize(){if(!self.crossOriginIsolated||typeof SharedArrayBuffer==='undefined')throw Error('HTTPSのページをChromeで開いてください。再読み込み後も起動しない場合は、対応ブラウザが必要です。');this.onStatus('loading','エンジンを準備しています…');this.worker=new Worker(new URL('./engine-worker.js',import.meta.url));this.worker.onmessage=({data})=>{if(data.type==='progress')this.onStatus('loading',data.text);for(const fn of [...this.listeners])fn(data);};this.worker.onerror=e=>{for(const fn of [...this.listeners])fn({type:'error',message:e.message||'エンジンを起動できませんでした。'});};let wait=this.waitFor(d=>d.type==='loaded',60000);this.worker.postMessage({type:'init'});await wait;
    wait=this.waitFor(d=>d.line==='usiok');this.send('usi');await wait;
    this.send('setoption name USI_Hash value 32');this.send('setoption name Threads value 1');this.send('setoption name USI_Ponder value false');this.send('setoption name USI_OwnBook value false');this.send('setoption name PvInterval value 200');this.send('setoption name EnteringKingRule value CSARule27');this.send('setoption name ResignValue value 99999');
    wait=this.waitFor(d=>d.line==='readyok');this.send('isready');await wait;this.send('usinewgame');this.ready=true;this.onStatus('ready','やねうら王 NNUE KP256');
  }
  async search(initial,moves,{time=3000,multipv=1,onInfo=()=>{}}={}){const generation=this.generation;validateAnalysisPosition(positionAt(initial,moves));await this.init();if(generation!==this.generation)throw new DOMException('解析を中止しました。','AbortError');if(this.searching)throw Error('別の解析が進行中です。');this.searching=true;const results=new Map();const handler=data=>{const info=data.type==='line'?parseInfo(data.line):null;if(info){results.set(info.rank,info);onInfo(info);}};this.listeners.add(handler);try{this.send('setoption name MultiPV value '+multipv);this.send('position sfen '+initial+(moves.length?' moves '+moves.join(' '):''));const wait=this.waitFor(d=>d.type==='line'&&d.line.startsWith('bestmove '),time+20000);this.send('go movetime '+time);const msg=await wait;return {bestmove:msg.line.split(' ')[1],infos:[...results.values()].sort((a,b)=>a.rank-b.rank)};}finally{this.listeners.delete(handler);this.searching=false;}}
  stop(){this.generation++;if(this.worker&&this.searching)this.send('stop');}
  terminate(){this.ready=false;this.searching=false;this.initPromise=null;if(this.worker){this.worker.terminate();this.worker=null;}for(const fn of [...this.listeners])fn({type:'error',message:'処理を中止しました。'});this.listeners.clear();}
}
